const body = $input.first().json.body || {};
const incoming = Array.isArray(body.file_ids) ? body.file_ids : [];
const fileIds = [...new Set(incoming.map(value => String(value || '').trim()).filter(Boolean))];
if (fileIds.length === 0) {
  throw new Error('file_ids must contain at least one Google Drive file ID');
}
if (fileIds.length > 200) {
  throw new Error('At most 200 Google Drive files may be removed per request');
}
const validId = /^[A-Za-z0-9_-]{10,200}$/;
for (const fileId of fileIds) {
  if (!validId.test(fileId)) throw new Error('Invalid Google Drive file ID');
}
return fileIds.map(fileId => ({ json: { file_id: fileId } }));
